export function formatWhatsAppOrderUrl(order: Partial<OrderRequest>, whatsappNumber: string = '962775179231'): string {
  const lines = [
    'مرحباً منصة دعوتك 👋',
    'أودّ طلب تصميم دعوة إلكترونية فاخرة بالتفاصيل التالية:',
    '',
    `• التصميم المختار: ${order.designName || 'تصميم من المجموعة'} (${order.designSlug || ''})`,
    `• الباقة: ${order.packageType === 'diamond' ? 'الباقة الماسية VIP' : order.packageType === 'gold' ? 'الباقة الذهبية الملكية' : 'الباقة الأساسية'}`,
    order.category ? `• نوع المناسبة: ${order.category}` : '',
    order.groomOrHostName ? `• الأسماء: ${order.groomOrHostName} ${order.brideName ? '& ' + order.brideName : ''}` : '',
    order.date ? `• موعد الحفل: ${order.date} ${order.time ? '- ' + order.time : ''}` : '',
    order.hallName ? `• القاعة والموقع: ${order.hallName} (${order.city || ''})` : '',
    order.phone ? `• رقم الهاتف: ${order.phone}` : '',
    order.notes ? `• ملاحظات أو تعديلات خاصة: ${order.notes}` : '',
    '',
    'بانتظار تواصلكم لإرسال التفاصيل وتجهيز الرابط، شكراً لكم! ✨'
  ].filter(line => line !== '');

  const text = encodeURIComponent(lines.join('\n'));
  return `https://wa.me/${whatsappNumber.replace(/\D/g, '')}?text=${text}`;
}

export function formatWhatsAppRsvpUrl(guestName: string, attending: boolean, guestsCount: number, coupleNames: string, whatsappNumber: string = '962775179231'): string {
  const status = attending ? 'يسعدني ويشرفني تأكيد الحضور بإذن الله ✅' : 'أعتذر عن الحضور لظروف خاصة، مبارك لكم وبالرفاه والبنين 💐';
  const lines = [
    `مرحباً، رد على دعوة حفل: ${coupleNames}`,
    `• اسم الضيف: ${guestName || 'ضيف كريم'}`,
    `• حالة الحضور: ${status}`,
    attending ? `• عدد المقاعد: ${guestsCount}` : ''
  ].filter(Boolean);

  const text = encodeURIComponent(lines.join('\n'));
  return `https://wa.me/${whatsappNumber.replace(/\D/g, '')}?text=${text}`;
}

